import{_ as t,a as o,b as a}from"./chunks/run-live.BHkhzNf5.js";import{_ as r}from"./chunks/report.BOAPNauD.js";import{_ as s,o as n,c as d,a2 as i}from"./chunks/framework.C1aUlgNS.js";const y=JSON.parse('{"title":"General workflow","description":"","frontmatter":{},"headers":[],"relativePath":"guide/workflow.md","filePath":"guide/workflow.md"}'),h={name:"guide/workflow.md"};function l(c,e,p,u,g,f){return n(),d("div",null,[...e[0]||(e[0]=[i('<h1 id="general-workflow" tabindex="-1">General workflow <a class="header-anchor" href="#general-workflow" aria-label="Permalink to &quot;General workflow&quot;">​</a></h1><p>This page walks from your own app to a passing Run in four steps. Each step ends with <strong>what can go wrong</strong>: the message you see, word for word, so you can search this page for it, and whether it points at your app, your setup, your test file, or Jevwright.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1 Pick the app  →  2 Write the test file  →  3 Upload it and set the Variables  →  4 Run it and read the report</span></span></code></pre></div><h2 id="_1-pick-the-app" tabindex="-1">1. Pick the app <a class="header-anchor" href="#_1-pick-the-app" aria-label="Permalink to &quot;1. Pick the app&quot;">​</a></h2><p>Use the <a href="./quick-start.html#the-demo-app">Demo App</a> to learn, or your own app. Your app must be on a <strong>public domain</strong> that our server can reach, because every Run happens there.</p><p>Decide how the test gets past the sign-in page:</p><ul><li><strong>A test user signs in through the form.</strong> Simplest, when the sign-in has no CAPTCHA or 2FA. Keep the password in a Variable, such as <code>{{APP_PASSWORD}}</code>.</li><li><strong>The test starts signed in.</strong> Copy the session cookie or the token from your browser&#39;s developer tools after you sign in, put it in a Variable, and set it with <code>cookies</code>, <code>headers</code>, <code>localStorage</code> or <code>sessionStorage</code> (see <a href="./../reference/test-file.html#headers-cookies-and-storage">Headers, cookies and storage</a>).</li></ul><h3 id="what-can-go-wrong" tabindex="-1">What can go wrong <a class="header-anchor" href="#what-can-go-wrong" aria-label="Permalink to &quot;What can go wrong&quot;">​</a></h3><table tabindex="0"><thead><tr><th>You see</th><th>Cause</th><th>Fix</th></tr></thead><tbody><tr><td><code>net::ERR_FAILED at http://localhost:3000/</code> or <code>net::ERR_CONNECTION_REFUSED at …</code> on the <code>open</code> step</td><td>The URL is not public: <code>localhost</code>, a private IP, an intranet or VPN-only host. Runs reach public addresses only</td><td>Deploy the app to a public domain and set <code>BASE</code> to it</td></tr><tr><td><code>net::ERR_NAME_NOT_RESOLVED at …</code></td><td>The host name does not exist on the public internet, or is misspelled</td><td>Check <code>BASE</code> in a browser on another network</td></tr><tr><td><code>net::ERR_CERT_…</code> or <code>net::ERR_SSL_…</code></td><td>The HTTPS certificate is invalid or self-signed</td><td>Use a valid certificate, or the app&#39;s <code>http://</code> URL if it serves one</td></tr><tr><td><code>The page did not finish loading within 15000ms</code></td><td>The page is slow, or keeps loading something that never finishes</td><td>Raise <code>timeoutMs</code>, or open a lighter page first</td></tr><tr><td>The test signs in on one Run and lands on the sign-in page on the next</td><td>The cookie or token in the Variable has expired</td><td>Sign in again, copy the new value, and update the Variable</td></tr><tr><td>A CAPTCHA, a &quot;check your email&quot; code or a bot check appears in the step screenshot</td><td>These cannot be automated</td><td>Use a test user without them, or start signed in with a cookie or token</td></tr><tr><td>Pages answer &quot;Too many requests&quot;, or the app blocks you after a few Runs</td><td>Your app rate-limits sign-ins or requests</td><td>Start signed in instead of signing in every Run, or allow-list test users</td></tr></tbody></table><p>These are your app&#39;s or your setup&#39;s problems, not Jevwright&#39;s: the same URL fails the same way in any browser on a public network.</p><h2 id="_2-write-the-test-file-with-your-agent" tabindex="-1">2. Write the test file with your agent <a class="header-anchor" href="#_2-write-the-test-file-with-your-agent" aria-label="Permalink to &quot;2. Write the test file with your agent&quot;">​</a></h2><p>Describe to your coding agent (Claude Code, Codex, Cursor, …) what to test, in your words: &quot;Sign in as the test user, add the first product to the cart, check out, and check that the order is confirmed.&quot; With the <a href="./agent-skill.html">Agent Skill</a> installed, the agent writes a Jevwright test file in the right syntax. You can also write the file yourself; the <a href="./../reference/test-file.html">YAML syntax</a> has everything.</p><p>Good test files:</p><ul><li>use a <code>selector</code> where the page has a stable one, such as <code>[data-test=&quot;checkout&quot;]</code> or <code>#email</code>, copied from the real page in your browser&#39;s developer tools;</li><li>use a <code>target</code> that describes what you see, such as <code>&quot;Blue &#39;Checkout&#39; button below the cart&quot;</code>, where there is no stable selector;</li><li>put the app&#39;s URL in <code>baseUrl: &quot;{{BASE}}&quot;</code>, and every password and token in a <code>{{VARIABLE}}</code>.</li></ul><h3 id="what-can-go-wrong-1" tabindex="-1">What can go wrong <a class="header-anchor" href="#what-can-go-wrong-1" aria-label="Permalink to &quot;What can go wrong&quot;">​</a></h3><table tabindex="0"><thead><tr><th>You see</th><th>Cause</th><th>Fix</th></tr></thead><tbody><tr><td><code>Unknown action &quot;aiAct&quot;</code>, <code>Unknown field &quot;colour&quot;</code> and other problems in the Debug console</td><td>The agent invented an action or a field</td><td>Paste the Debug console&#39;s lines back to the agent and ask it to fix every one. See <a href="./../reference/diagnostics.html">Diagnostics</a></td></tr><tr><td><code>No element matches &quot;#login-btn&quot; within 15000ms</code> when it runs</td><td>The agent guessed a selector without seeing the page</td><td>Copy the selector from the real page, or add a <code>target</code> so Jev can find the element when the selector fails</td></tr><tr><td>A password or token in the file itself</td><td>The agent wrote the value instead of a Variable</td><td>Replace it with <code>{{NAME}}</code> and set the Variable on the Project</td></tr></tbody></table><h2 id="_3-upload-it-and-set-the-variables" tabindex="-1">3. Upload it and set the Variables <a class="header-anchor" href="#_3-upload-it-and-set-the-variables" aria-label="Permalink to &quot;3. Upload it and set the Variables&quot;">​</a></h2><p>In the web workspace, create a Project with the <strong>+</strong> next to &quot;Projects&quot; (1) if you have none. Then open the <strong>+</strong> menu on a Project or a folder and choose <strong>Upload files…</strong> (2), or drag <code>.yaml</code> files or whole folders from your computer onto a Project or folder in the sidebar. You can also choose <strong>New test file</strong> in the same menu and paste the YAML into the editor.</p><p><img src="'+t+'" alt="The sidebar with markers on the + next to Projects (1) and the menu of a folder&#39;s + with New folder, New test file and Upload files… (2); markers 3 and 4 show the status icons of a passed and a failed file"></p><p>Then click the key icon on the Project&#39;s row to open its Variables, and set every Variable the file uses, such as <code>BASE</code>: type its <strong>Name</strong> (3) and <strong>Value</strong> (4) and click <strong>Save</strong> (5). Every file in the Project, in any folder, uses the Project&#39;s Variables.</p><p><img src="'+o+'" alt="The Variables page of the Quick Start project, with markers on the row of BASE (1), its eye button (2), the Name field (3), the Value field (4) and Save (5)"></p><p>The file is checked when it arrives and every time you save: the <strong>Debug console</strong> lists every problem with its line.</p><h3 id="what-can-go-wrong-2" tabindex="-1">What can go wrong <a class="header-anchor" href="#what-can-go-wrong-2" aria-label="Permalink to &quot;What can go wrong&quot;">​</a></h3><table tabindex="0"><thead><tr><th>You see</th><th>Cause</th><th>Fix</th></tr></thead><tbody><tr><td><code>Only .yaml and .yml files can be imported.</code></td><td>The file has another extension</td><td>Rename it to <code>.yaml</code>. A <code>.yml</code> file is renamed to <code>.yaml</code> for you</td></tr><tr><td><code>Test file names use only letters, digits, -, _ and ., with no spaces, and end in .yaml.</code></td><td>The file name has spaces or other characters</td><td>Rename it, such as <code>checkout-total.yaml</code></td></tr><tr><td><code>Folders can be at most 4 levels deep, counting the project.</code></td><td>The folder you dropped is nested too deep</td><td>Flatten the folders: a Project and at most three levels of folders under it</td></tr><tr><td><code>The test file is too long: it can be at most 262,144 characters.</code></td><td>The file is larger than a test file can be</td><td>Split it into several files</td></tr><tr><td><code>A folder or test file with this name already exists in this folder.</code> (or <code>… in this project.</code>) in the skipped list</td><td>A file of that name is already there; nothing is overwritten</td><td>Rename the file, or delete the old one first</td></tr><tr><td><code>Variable names use capital letters, digits and _, and do not start with a digit, for example BASE_URL.</code></td><td>The Variable name in the Variables form is not valid</td><td>Use names such as <code>BASE</code> or <code>APP_PASSWORD</code>, as the file writes them</td></tr><tr><td>Problems in the Debug console after the upload</td><td>The file breaks the syntax</td><td>Fix them, or paste them back to your agent; a file with problems cannot run</td></tr></tbody></table><h2 id="_4-run-it-and-read-the-report" tabindex="-1">4. Run it and read the report <a class="header-anchor" href="#_4-run-it-and-read-the-report" aria-label="Permalink to &quot;4. Run it and read the report&quot;">​</a></h2><p>Click <strong>Run</strong> at the top right of the editor. The <strong>Output console</strong> follows each step live: the Run&#39;s status (1), the steps that passed (2), the one running (3) and the ones still to come (4).</p><p><img src="'+a+'" alt="The Output console during a Run, with markers on the Running badge (1), the passed step 1 (2), the running step 2 (3) and the pending steps 3 to 8 (4)"></p><p>When the Run ends, <strong>Open run details</strong> shows the report: the Run&#39;s status (1), each step&#39;s status and duration, how its element was found (5), the reason of a failed step, and a screenshot of the page after each step (4).</p><p><img src="'+r+'" alt="A report beside the editor, with markers on the status (1), Open full page (2), Download report (3), the screenshot of step 1 (4) and the locate method &quot;selector&quot; of step 2 (5)"></p><p>The report also offers <strong>Download report</strong> (3), the JSON report, and <strong>Download trace</strong>, a Playwright trace that you can open at <a href="https://trace.playwright.dev" target="_blank" rel="noreferrer">trace.playwright.dev</a> to step through the Run with the page, the network and the console.</p><p>A Run stops at the first failed step; the steps after it stay <strong>Pending</strong>. The file&#39;s <strong>History</strong>, below the steps in the Output console, keeps every Run, newest first; click one to open its report.</p><h3 id="what-can-go-wrong-3" tabindex="-1">What can go wrong <a class="header-anchor" href="#what-can-go-wrong-3" aria-label="Permalink to &quot;What can go wrong&quot;">​</a></h3><table tabindex="0"><thead><tr><th>You see</th><th>Cause</th><th>Points at</th></tr></thead><tbody><tr><td><code>Variable {{BASE}} is not set</code></td><td>The Project has no Variable of that name</td><td>Your setup: add the Variable on the Project that holds the file</td></tr><tr><td><code>The page did not finish loading within 15000ms</code></td><td>The page is slow to load</td><td>Your app, or a <code>timeoutMs</code> too short for it</td></tr><tr><td><code>No element matches &quot;[data-test=&quot;checkout&quot;]&quot; within 15000ms</code></td><td>No element on the page matches the selector</td><td>Your test file (a wrong selector) or your app (the page changed, or showed something else: look at the screenshot)</td></tr><tr><td><code>&quot;#save&quot; was found but could not be clicked within 15000ms: it stayed hidden, disabled, or covered by another element</code></td><td>The element is there but cannot be used, often behind a cookie banner or a dialog</td><td>Your app: close the banner in an earlier step, or wait for the page</td></tr><tr><td><code>Could not locate &quot;Green Login button&quot;:</code> followed by one line per method, such as <code>visual — confidence 0.4 below 0.7</code></td><td>Jev could not find what the <code>target</code> describes with enough confidence</td><td>Your test file: describe the element as it looks, with its text, color and position, or add a <code>selector</code></td></tr><tr><td><code>Text of &quot;[data-test=&quot;title&quot;]&quot; did not contain &quot;Products&quot; within 15000ms; it was &quot;Your Cart&quot;</code></td><td>The element&#39;s text is not what the step expects</td><td>Your app&#39;s behavior, or the test&#39;s expectation</td></tr><tr><td><code>The URL did not match &quot;**/inventory.html&quot; within 15000ms; it was &quot;https://…/&quot;</code></td><td>The page did not go where the step expects, often a failed sign-in</td><td>Your app or your test file; look at the screenshot of the step before</td></tr><tr><td><code>Statement does not hold (noul=0.05)</code></td><td>Jev judged the <code>statement</code> false from the screenshot</td><td>Usually your app; <code>noul</code> is how likely Jev thinks the statement is true, from 0 to 1. Look at the screenshot</td></tr><tr><td><code>Statement is uncertain after 2 asks (noul=0.5)</code></td><td>Jev could not decide</td><td>Your test file: make the statement more specific, or check it with a selector</td></tr><tr><td><code>Unexpected alert dialog: &quot;Profile saved&quot;</code></td><td>The page opened a dialog that the step does not answer</td><td>Your test file: add <a href="./../reference/actions.html#dialogs"><code>dialog</code></a> to the step that opens it</td></tr><tr><td><code>The run did not finish within runTimeoutMs (600000 ms)</code></td><td>The whole Run took too long</td><td>Your test file: split it, or raise <code>runTimeoutMs</code> (a Run lasts at most 10 minutes)</td></tr><tr><td>A step passes on one Run and fails on the next</td><td>The app is slow or changes between Runs (data, A/B tests, ads), or a Jev answer differed</td><td>Your app or your test file: wait for the page with <code>waitFor</code>, and prefer selectors for steps that must never vary</td></tr><tr><td><code>Browser error: …</code> or <code>Something went wrong while running the test. Try running it again.</code></td><td>The browser or the server failed during the Run</td><td>Jevwright: run it again, and report it if it keeps happening</td></tr></tbody></table><h3 id="is-it-my-app-my-test-or-jevwright" tabindex="-1">Is it my app, my test, or Jevwright? <a class="header-anchor" href="#is-it-my-app-my-test-or-jevwright" aria-label="Permalink to &quot;Is it my app, my test, or Jevwright?&quot;">​</a></h3><ol><li><strong>Look at the step&#39;s screenshot.</strong> If the page shows an error, a sign-in page, a banner or an unexpected state, the cause is the app or the session: open the same URL in your browser.</li><li><strong>Read the reason.</strong> Messages about selectors, text, URLs and statements describe what the browser found; compare them with the page in the screenshot. Messages starting with <code>net::</code> are about reaching the app.</li><li><strong>Open the trace</strong> for the full story: every action, request and console message, with the page before and after.</li><li><strong>Report a Jevwright bug</strong> when the screenshot shows the element the step needs, the selector matches it in your browser&#39;s developer tools, and the step still fails, or for <code>Browser error</code> and <code>Something went wrong</code> messages that repeat. Open an issue at <a href="https://github.com/yike2/Jevwright/issues" target="_blank" rel="noreferrer">github.com/yike2/Jevwright</a> with the test file and the downloaded report.</li></ol>',35)])])}const k=s(h,[["render",l]]);export{y as __pageData,k as default};
